// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.detectionimport timber.log.Timberimport com.roshan.persona.vision.core.ConfidenceThresholdsimport com.roshan.persona.vision.ocr.GrayscaleImageimport com.roshan.persona.vision.ocr.RgbImageimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Object Detection Engine (Module 6 v4 — Step 6.3, MAIN ORCHESTRATOR). * * The single entry point for real-time object detection + tracking. Combines: *  - [ObjectDetector] — SSD MobileNetV3 inference + NMS *  - [RealTimeTracker] — SORT (Simple Online Realtime Tracking) *  - [MotionGatingController] — adaptive FPS (0 → 20 FPS based on motion) * * ## Pipeline (per strategy v4 §"Architecture → ObjectDetectionEngine") * * ``` * Camera frame (30 FPS, RGB) → *   ↓ * 1. Convert to grayscale (for Motion Gating) *   ↓ * 2. MotionGatingController.processFrame() → MotionDecision *    - If STATIC (skip) → return empty frame (battery saved) *    - If SLOW/NORMAL/RAPID → continue to detection *   ↓ * 3. ObjectDetector.detect(frame) → List<DetectedObject> (NMS-filtered) *   ↓ * 4. RealTimeTracker.update(detections) → List<DetectedObject> (with trackIds) *   ↓ * 5. Build DetectionFrame + apply confidence tiers *   ↓ * 6. Return TieredDetectionResult * ``` * * ## Confidence Thresholds (per strategy v4 §"Issue 1") * *  - ≥ 0.50 → display (bounding box on UI) *  - ≥ 0.70 → speak (TTS announces label) *  - < 0.50 → suppress * * ## Battery Impact (per strategy v4 §"Upgrade 3") * * With Motion Gating enabled: *  - Static scene: 0 FPS inference → 8+ hours battery *  - Normal motion: 15 FPS → 5.5 hours *  - Rapid motion: 20 FPS → 3 hours * * ## Testability * * All native dependencies are injected (FrameDifferencer, SsdModelDelegate). * Tests use FakeFrameDifferencer + FakeSsdDelegate to verify orchestration * without native libraries. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.3: ObjectDetectionEngine</a> */class ObjectDetectionEngine(    private val detector: ObjectDetector,    private val tracker: RealTimeTracker,    private val motionGatingController: MotionGatingController,    private val grayscaleConverter: GrayscaleConverter,    private val dispatcher: CoroutineDispatcher,) {    /**     * Process a single camera frame.     *     * @param frame the RGB camera frame.     * @return tiered detection result (HIGH/MEDIUM/LOW/REJECT based on max confidence).     */    suspend fun processFrame(frame: RgbImage): TieredDetectionResult = withContext(dispatcher) {        val frameTimestampMs = System.currentTimeMillis()        // 1. Convert to grayscale for Motion Gating (cheap operation).        val grayscale = grayscaleConverter.toGrayscale(frame)        // 2. Run Motion Gating.        val motionDecision = motionGatingController.processFrame(grayscale)        // 3. If STATIC → skip inference (battery saved).        if (motionDecision.inferenceSkipped) {            Timber.tag(TAG).v("Skipping detection (motion=${motionDecision.motionPercent}%, state=${motionDecision.motionState}).")            val skippedFrame = DetectionFrame(                objects = emptyList(),                frameTimestampMs = frameTimestampMs,                processingTimeMs = 0,                motionState = motionDecision.motionState,                inferenceSkipped = true,            )            return@withContext tieredDetectionResult(skippedFrame)        }        // 4. Run object detection (SSD + NMS).        val detectionStart = System.currentTimeMillis()        val detections = detector.detect(frame)        val detectionMs = System.currentTimeMillis() - detectionStart        // 5. Run tracking (SORT).        val trackedDetections = tracker.update(detections, frameTimestampMs)        // 6. Build the detection frame.        val detectionFrame = DetectionFrame(            objects = trackedDetections,            frameTimestampMs = frameTimestampMs,            processingTimeMs = detectionMs,            motionState = motionDecision.motionState,            inferenceSkipped = false,        )        Timber.tag(TAG).d("Frame processed: ${trackedDetections.size} objects, " +            "motion=${motionDecision.motionPercent}%, ${detectionMs}ms.")        tieredDetectionResult(detectionFrame)    }    /**     * Get all active tracks (for UI overlay of track IDs).     */    fun activeTracks(): List<TrackingTrack> = tracker.activeTracks()    /**     * Get a specific track by ID.     */    fun trackById(trackId: Int): TrackingTrack? = tracker.trackById(trackId)    /**     * Reset the engine (clears tracks + motion gating state).     * Called when the camera is reopened or user starts a new session.     */    fun reset() {        tracker.reset()        motionGatingController.reset()        Timber.tag(TAG).i("ObjectDetectionEngine reset.")    }    /**     * Get Motion Gating stats (for Settings UI).     */    fun motionGatingStats(): MotionGatingStats = motionGatingController.stats()    /**     * Get the current motion state.     */    fun currentMotionState(): MotionState = motionGatingController.currentMotionState()    /**     * Get the last motion percentage.     */    fun currentMotionPercent(): Float = motionGatingController.currentMotionPercent()    /**     * Get tracker stats.     */    fun trackerStats(): TrackerStats = TrackerStats(        activeTrackCount = tracker.trackCount(),        totalTracksCreated = tracker.totalTracksCreated(),    )    /**     * Get supported detection classes.     */    fun supportedClasses(): List<DetectionClass> = detector.supportedClasses()    private companion object {        private const val TAG = "ObjectDetectionEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** Tracker stats for Settings UI. */data class TrackerStats(    val activeTrackCount: Int,    val totalTracksCreated: Int,)// ──────────────────────────────────────────────────────────────────────────/** * Grayscale converter interface — abstracts RGB → grayscale conversion. * * Production: [OpenCvGrayscaleConverter] uses OpenCV's cvtColor. * Tests: [FakeGrayscaleConverter] returns a canned grayscale image. */interface GrayscaleConverter {    /** Convert an RGB image to grayscale. */    fun toGrayscale(image: RgbImage): GrayscaleImage}
